// generated by lin-rewrite → zig
const std = @import("std");
pub var LIA_ALLOC: std.mem.Allocator = undefined;

fn _lia_str(x: anytype) []const u8 {
    const T = @TypeOf(x);
    if (T == []const u8) return x;
    if (T == []u8) return x;
    if (T == bool) return if (x) "true" else "false";
    return switch (@typeInfo(T)) {
        .int, .comptime_int => std.fmt.allocPrint(LIA_ALLOC, "{d}", .{x}) catch "",
        .float, .comptime_float => std.fmt.allocPrint(LIA_ALLOC, "{d}", .{x}) catch "",
        else => "",
    };
}
pub fn _lia_cat(a: anytype, b: anytype) []const u8 {
    return std.mem.concat(LIA_ALLOC, u8, &.{ _lia_str(a), _lia_str(b) }) catch "";
}
fn _lia_eqs(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}

pub fn collatz(n: i64) i64 {
    var count: i64 = 0;
    var cur: i64 = 0;
    count = 0;
    cur = n;
    while (cur > 1) {
        if (@rem(cur, 2) == 0) {
            cur = @divTrunc(cur, 2);
        } else {
            cur = 3 * cur + 1;
        }
        count = count + 1;
    }
    return count;
}

pub fn power(base: i64, exp: i64) i64 {
    var res: i64 = 0;
    var i: i64 = 0;
    res = 1;
    i = 0;
    while (i < exp) {
        res = res * base;
        i = i + 1;
    }
    return res;
}


pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    LIA_ALLOC = gpa.allocator();

    const c27 = collatz(27);
    const p10 = power(2, 10);
    std.debug.assert(c27 == 111);
    std.debug.assert(p10 == 1024);

    const stdout = std.io.getStdOut().writer();
    try stdout.print("ZIG_VERIFIED: collatz={d} power={d}\n", .{ c27, p10 });
}
